    freq = Counter(
        grid[r][c]
        for r in range(3, h)
        for c in range(3, w)
        if grid[r][c] != 0
    )
    threshold = max(4, (h * w) // 200)
    colors = {color for color, count in freq.items() if count >= threshold}

    # Horizontal neighbors reveal the order of the repeating palette.
    edges = {color: Counter() for color in colors}
    for r in range(3, h):
        for c in range(3, w - 1):
            a, b = grid[r][c], grid[r][c + 1]
            if a in colors and b in colors:
                edges[a][b] += 1
    successor = {
        color: max(edges[color], key=edges[color].get)
        for color in colors
        if edges[color]
    }

    # Follow the dominant successor relation to obtain the palette cycle.
    cycles = []
    for start in successor:
        path, positions, node = [], {}, start
        while node in successor and node not in positions:
            positions[node] = len(path)
            path.append(node)
            node = successor[node]
        if node in positions:
            cycle = path[positions[node]:]
            if len(cycle) > len(cycles):
