def transform(grid):
    """Restore holes in a framed grid whose interior rows repeat a color cycle."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Recover the horizontal palette cycle from the repeated interior runs.
    counts = Counter(grid[r][c] for r in range(3, h) for c in range(3, w)
                     if grid[r][c] != 0)
    palette = {color for color, count in counts.items() if count >= 4}
    edges = {color: Counter() for color in palette}
    for r in range(3, h):
        for c in range(3, w - 1):
            a, b = grid[r][c], grid[r][c + 1]
            if a in palette and b in palette:
                edges[a][b] += 1
    successor = {color: max(nexts, key=nexts.get)
                 for color, nexts in edges.items() if nexts}

    cycles = []
    for start in successor:
        path, seen, node = [], {}, start
        while node in successor and node not in seen:
            seen[node] = len(path)
            path.append(node)
            node = successor[node]
        if node in seen:
            cycle = path[seen[node]:]
            if len(cycle) > len(cycles):
                cycles = cycle
    if not cycles:
        cycles = sorted(palette) or [1]
    position = {color: i for i, color in enumerate(cycles)}

    # Each patterned row has its own phase. Infer it by majority from the
    # unmasked cells, which also tolerates a few anomalous cells at the start.
    phases = []
    for r in range(3, h):
        votes = Counter((position[grid[r][c]] - c) % len(cycles)
                        for c in range(3, w) if grid[r][c] in position)
        phases.append(votes.most_common(1)[0][0] if votes else
                      (phases[-1] if phases else 0))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = cycles[(c + phases[r - 3]) % len(cycles)]
    return out


if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.load(sys.stdin))))
